//! Deterministic native regressions for the directory acquisition boundary.

use std::cell::Cell;
use std::cell::RefCell;
use std::fs;
use std::fs::File;
use std::io;
use std::path::Path;
use std::process::Command;
use std::rc::Rc;

use pretty_assertions::assert_eq;
use windows_sys::Win32::Storage::FileSystem::CreateDirectoryW;

use super::super::final_path;
use super::super::open_private_state_directory;
use super::super::wide_path;
use super::super::with_private_security;

type BeforeOpenHook = Box<dyn FnOnce() -> io::Result<()>>;
thread_local! {
    static BEFORE_OPEN: RefCell<Option<BeforeOpenHook>> = const { RefCell::new(None) };
}

pub(super) fn before_open() -> io::Result<()> {
    // Remove it before invocation, so setup failures or nested opens cannot
    // consume it twice or leave a RefCell borrowed across filesystem operations.
    let hook = BEFORE_OPEN.with(|slot| slot.borrow_mut().take());
    match hook {
        Some(hook) => hook(),
        None => Ok(()),
    }
}

struct HookGuard;

impl HookGuard {
    fn install(hook: impl FnOnce() -> io::Result<()> + 'static) -> Self {
        let previous = BEFORE_OPEN.with(|slot| slot.borrow_mut().replace(Box::new(hook)));
        assert!(previous.is_none(), "only one acquisition hook per thread");
        Self
    }
}

impl Drop for HookGuard {
    fn drop(&mut self) {
        BEFORE_OPEN.with(|slot| slot.borrow_mut().take());
    }
}

fn junction(target: &Path, alias: &Path) -> io::Result<()> {
    // Directory junctions require no symlink privilege. Failure is a fixture
    // failure, never an optional skip or evidence that acquisition was denied.
    let output = Command::new("cmd")
        .args(["/C", "mklink", "/J"])
        .arg(alias)
        .arg(target)
        .output()?;
    if !output.status.success() {
        return Err(io::Error::other(format!(
            "mklink /J failed: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    Ok(())
}

fn private_directory_fixture(path: &Path) -> io::Result<File> {
    let wide = wide_path(path)?;
    with_private_security(|security| {
        if unsafe { CreateDirectoryW(wide.as_ptr(), security) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    })?;
    open_private_state_directory(path)
}

#[test]
fn rejects_junction_before_creating_private_leaf() -> io::Result<()> {
    let temporary = tempfile::tempdir()?;
    let outside = temporary.path().join("outside");
    let alias = temporary.path().join("alias");
    fs::create_dir(&outside)?;
    junction(&outside, &alias)?;
    let outside_leaf = outside.join("registry");
    assert!(!outside_leaf.try_exists()?);

    let result = open_private_state_directory(&alias.join("registry"));
    let denied = result.is_err();
    drop(result);
    let created = outside_leaf.try_exists()?;
    fs::remove_dir(&alias)?;
    eprintln!("PRIVATE_STATE_ACQUISITION creation denied={denied} created={created}");
    assert!(denied, "a reparse ancestor must be rejected");
    assert!(
        !created,
        "rejection must not first create the redirected leaf"
    );
    Ok(())
}

#[test]
fn rejects_ancestor_substitution_at_retained_open() -> io::Result<()> {
    let temporary = tempfile::tempdir()?;
    let ancestor = temporary.path().join("ancestor");
    let parked = temporary.path().join("parked");
    let outside = temporary.path().join("outside");
    fs::create_dir(&ancestor)?;
    fs::create_dir(&outside)?;
    let root = ancestor.join("registry");
    let outside_root = outside.join("registry");
    // Both leaves have the actual private current-user descriptor. A redirected
    // open therefore cannot be rejected merely because our fixture has bad ACLs.
    drop(private_directory_fixture(&root)?);
    let outside_handle = private_directory_fixture(&outside_root)?;
    let expected_redirect = final_path(&outside_handle)?;
    drop(outside_handle);

    let substituted = Rc::new(Cell::new(false));
    let observed = Rc::clone(&substituted);
    let hook_ancestor = ancestor.clone();
    let hook = HookGuard::install(move || {
        fs::rename(&hook_ancestor, &parked)?;
        junction(&outside, &hook_ancestor)?;
        observed.set(true);
        Ok(())
    });
    let result = open_private_state_directory(&root);
    drop(hook);
    let denied = result.is_err();
    let redirected = match &result {
        Ok(handle) => final_path(handle)? == expected_redirect,
        Err(_) => false,
    };
    drop(result);
    assert!(
        substituted.get(),
        "the real ancestor substitution must complete"
    );
    fs::remove_dir(&ancestor)?;
    eprintln!(
        "PRIVATE_STATE_ACQUISITION substitution swapped=true denied={denied} redirected={redirected}"
    );
    assert_eq!((denied, redirected), (true, false));
    Ok(())
}

//! Creation-only Windows security descriptor with an explicit current-user owner.

use std::io;

use super::CurrentUser;
use windows_sys::Win32::Security::ACCESS_ALLOWED_ACE;
use windows_sys::Win32::Security::ACL;
use windows_sys::Win32::Security::ACL_REVISION;
use windows_sys::Win32::Security::AddAccessAllowedAceEx;
use windows_sys::Win32::Security::CONTAINER_INHERIT_ACE;
use windows_sys::Win32::Security::GetLengthSid;
use windows_sys::Win32::Security::InitializeAcl;
use windows_sys::Win32::Security::InitializeSecurityDescriptor;
use windows_sys::Win32::Security::OBJECT_INHERIT_ACE;
use windows_sys::Win32::Security::SE_DACL_PROTECTED;
use windows_sys::Win32::Security::SECURITY_ATTRIBUTES;
use windows_sys::Win32::Security::SECURITY_DESCRIPTOR;
use windows_sys::Win32::Security::SetSecurityDescriptorControl;
use windows_sys::Win32::Security::SetSecurityDescriptorDacl;
use windows_sys::Win32::Security::SetSecurityDescriptorOwner;
use windows_sys::Win32::Storage::FileSystem::FILE_ALL_ACCESS;

// The owner SID and ACL storage stay alive through the creation call. An
// explicit owner avoids elevated tokens' Administrators default owner, while
// the protected DACL avoids any initially inherited public-access window.
pub(super) fn with_private_security<T>(
    create: impl FnOnce(&SECURITY_ATTRIBUTES) -> io::Result<T>,
) -> io::Result<T> {
    let current_user = CurrentUser::read()?;
    let sid_length = unsafe { GetLengthSid(current_user.sid()) } as usize;
    if sid_length == 0 {
        return Err(io::Error::last_os_error());
    }
    let acl_bytes = std::mem::size_of::<ACL>() + std::mem::size_of::<ACCESS_ALLOWED_ACE>()
        - std::mem::size_of::<u32>()
        + sid_length;
    let mut storage = vec![0_u32; acl_bytes.div_ceil(std::mem::size_of::<u32>())];
    let dacl = storage.as_mut_ptr().cast::<ACL>();
    if unsafe { InitializeAcl(dacl, acl_bytes as u32, ACL_REVISION) } == 0 {
        return Err(io::Error::last_os_error());
    }
    if unsafe {
        AddAccessAllowedAceEx(
            dacl,
            ACL_REVISION,
            OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE,
            FILE_ALL_ACCESS,
            current_user.sid(),
        )
    } == 0
    {
        return Err(io::Error::last_os_error());
    }
    let mut descriptor: SECURITY_DESCRIPTOR = unsafe { std::mem::zeroed() };
    let descriptor_ptr = (&mut descriptor as *mut SECURITY_DESCRIPTOR).cast();
    if unsafe {
        InitializeSecurityDescriptor(descriptor_ptr, /*dwrevision*/ 1)
    } == 0
        || unsafe {
            SetSecurityDescriptorOwner(
                descriptor_ptr,
                current_user.sid(),
                /*bownerdefaulted*/ 0,
            )
        } == 0
        || unsafe {
            SetSecurityDescriptorDacl(
                descriptor_ptr,
                /*bdaclpresent*/ 1,
                dacl,
                /*bdacldefaulted*/ 0,
            )
        } == 0
        || unsafe {
            SetSecurityDescriptorControl(descriptor_ptr, SE_DACL_PROTECTED, SE_DACL_PROTECTED)
        } == 0
    {
        return Err(io::Error::last_os_error());
    }
    let attributes = SECURITY_ATTRIBUTES {
        nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
        lpSecurityDescriptor: descriptor_ptr,
        bInheritHandle: 0,
    };
    create(&attributes)
}

//! Native Windows creation-security regressions; run with normal and elevated tokens.

use super::*;
use pretty_assertions::assert_eq;
use windows_sys::Win32::Security::GetKernelObjectSecurity;
use windows_sys::Win32::Security::GetSecurityDescriptorDacl;
use windows_sys::Win32::Security::GetSecurityDescriptorOwner;
use windows_sys::Win32::Security::SECURITY_ATTRIBUTES;
use windows_sys::Win32::Security::TOKEN_OWNER;
use windows_sys::Win32::Security::TokenOwner;

fn descriptor(file: &File) -> io::Result<Vec<u8>> {
    let mut length = 0;
    let information = OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION;
    unsafe {
        GetKernelObjectSecurity(
            file.as_raw_handle() as HANDLE,
            information,
            ptr::null_mut(),
            /*nlength*/ 0,
            &mut length,
        );
    }
    if length == 0 {
        return Err(io::Error::last_os_error());
    }
    let mut bytes = vec![0_u8; length as usize];
    if unsafe {
        GetKernelObjectSecurity(
            file.as_raw_handle() as HANDLE,
            information,
            bytes.as_mut_ptr().cast(),
            length,
            &mut length,
        )
    } == 0
    {
        return Err(io::Error::last_os_error());
    }
    Ok(bytes)
}

fn read_only_descriptor(security: &SECURITY_ATTRIBUTES) -> io::Result<()> {
    let mut present = 0;
    let mut defaulted = 0;
    let mut dacl = ptr::null_mut();
    if unsafe {
        GetSecurityDescriptorDacl(
            security.lpSecurityDescriptor,
            &mut present,
            &mut dacl,
            &mut defaulted,
        )
    } == 0
        || present == 0
        || dacl.is_null()
    {
        return Err(io::Error::last_os_error());
    }
    let mut ace = ptr::null_mut();
    if unsafe {
        GetAce(dacl, /*dwaceindex*/ 0, &mut ace)
    } == 0
    {
        return Err(io::Error::last_os_error());
    }
    if ace.is_null() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "security fixture returned a null ACE",
        ));
    }
    // Fixtures must use the same checked Win32 ACL span as production before
    // inspecting or modifying the returned ACE. Never assume GetAce's pointer
    // can be dereferenced based on non-null alone.
    if unsafe { IsValidAcl(dacl) } == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "security fixture returned an invalid ACL",
        ));
    }
    let mut info: ACL_SIZE_INFORMATION = unsafe { std::mem::zeroed() };
    if unsafe {
        GetAclInformation(
            dacl,
            (&mut info as *mut ACL_SIZE_INFORMATION).cast(),
            std::mem::size_of::<ACL_SIZE_INFORMATION>() as u32,
            AclSizeInformation,
        )
    } == 0
    {
        return Err(io::Error::last_os_error());
    }
    let acl_start = dacl as usize;
    let ace_start = ace as usize;
    let acl_bytes_in_use = info.AclBytesInUse as usize;
    if !ace_span_fits_acl(
        acl_start,
        acl_bytes_in_use,
        ace_start,
        std::mem::size_of::<ACE_HEADER>(),
    ) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "security fixture ACE header lies outside the ACL",
        ));
    }
    let header = unsafe { ptr::read_unaligned(ace.cast::<ACE_HEADER>()) };
    if header.AceType != ACCESS_ALLOWED_ACE_TYPE
        || !sid_length_fits_ace(usize::from(header.AceSize), 0)
        || !ace_span_fits_acl(
            acl_start,
            acl_bytes_in_use,
            ace_start,
            usize::from(header.AceSize),
        )
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "security fixture returned an invalid allow ACE",
        ));
    }
    // Restrict only this new fixture's descriptor before creation. No existing
    // object is made public or has its owner/security changed for this test.
    // Write the checked Mask field without forming an unchecked ACE reference.
    let mask_offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, Mask);
    let mask = unsafe { ace.cast::<u8>().add(mask_offset).cast::<u32>() };
    unsafe { ptr::write_unaligned(mask, FILE_GENERIC_READ) };
    Ok(())
}

#[test]
fn new_directory_and_child_have_explicit_token_user_ownership() {
    let current_user = CurrentUser::read().expect("current user");
    let mut length = 0;
    unsafe {
        GetTokenInformation(
            current_user.token,
            TokenOwner,
            ptr::null_mut(),
            /*tokeninformationlength*/ 0,
            &mut length,
        );
    }
    assert!(length > 0);
    let mut default_owner = vec![0_u8; length as usize];
    assert_ne!(
        unsafe {
            GetTokenInformation(
                current_user.token,
                TokenOwner,
                default_owner.as_mut_ptr().cast(),
                length,
                &mut length,
            )
        },
        0
    );
    let token_owner = unsafe { ptr::read_unaligned(default_owner.as_ptr().cast::<TOKEN_OWNER>()) };
    eprintln!(
        "token_default_owner_matches_user={}",
        unsafe { EqualSid(token_owner.Owner, current_user.sid()) } != 0
    );

    let temporary = tempfile::tempdir().expect("tempdir");
    let root = temporary.path().join("owner");
    let directory = open_private_state_directory(&root).expect("private directory");
    let child = open_private_state_child(&directory, "state", PrivateFileAccess::Create)
        .expect("private child");
    for file in [&directory, &child] {
        let mut bytes = descriptor(file).expect("created security descriptor");
        let mut owner = ptr::null_mut();
        let mut defaulted = 1;
        assert_ne!(
            unsafe {
                GetSecurityDescriptorOwner(bytes.as_mut_ptr().cast(), &mut owner, &mut defaulted)
            },
            0
        );
        assert_ne!(unsafe { EqualSid(owner, current_user.sid()) }, 0);
        assert_eq!(defaulted, 0);
        validate_private_owner_and_dacl(file).expect("private owner and DACL");
    }
}

#[test]
fn opening_existing_objects_never_rewrites_their_security() {
    let temporary = tempfile::tempdir().expect("tempdir");
    let restricted_root = temporary.path().join("read-only-root");
    let wide = wide_path(&restricted_root).expect("wide root");
    with_private_security(|security| {
        read_only_descriptor(security)?;
        if unsafe { CreateDirectoryW(wide.as_ptr(), security) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    })
    .expect("read-only fixture directory");
    let restricted_directory = OpenOptions::new()
        .read(true)
        .custom_flags(FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT)
        .open(&restricted_root)
        .expect("read descriptor handle");
    let before = descriptor(&restricted_directory).expect("original directory security");
    // A privileged token may open this directory despite the read-only DACL.
    // Either outcome must leave the existing descriptor exactly unchanged.
    drop(open_private_state_directory(&restricted_root));
    assert_eq!(
        descriptor(&restricted_directory).expect("after open"),
        before
    );

    let directory = open_private_state_directory(&temporary.path().join("private-root"))
        .expect("private directory");
    let wide =
        wide_path(&child_path(&directory, "state").expect("child path")).expect("wide child");
    let child = with_private_security(|security| {
        read_only_descriptor(security)?;
        let handle = unsafe {
            CreateFileW(
                wide.as_ptr(),
                FILE_GENERIC_READ,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                security,
                CREATE_NEW,
                FILE_FLAG_OPEN_REPARSE_POINT,
                /*htemplatefile*/ 0,
            )
        };
        if handle == INVALID_HANDLE_VALUE {
            return Err(io::Error::last_os_error());
        }
        Ok(unsafe { File::from_raw_handle(handle as *mut c_void) })
    })
    .expect("read-only fixture child");
    let before = descriptor(&child).expect("original child security");
    drop(open_private_state_child(
        &directory,
        "state",
        PrivateFileAccess::Create,
    ));
    assert_eq!(descriptor(&child).expect("after open"), before);
}

