fn stage_raw(
    owner: &AgentdPromptRuntimeOwner,
    thread_id: &str,
    turn_id: &str,
    value: PromptRuntimeAttachmentV1,
) {
    owner
        .commit_state(|state| {
            state.staged.insert(
                PromptRuntimeKey {
                    thread_id: thread_id.to_owned(),
                    turn_id: turn_id.to_owned(),
                },
                value,
            );
            Ok(())
