        request_binding_id: request_binding_id.to_owned(),
        provider_request_digest,
        outcome: PromptRuntimeTerminalOutcomeV1::Delivered,
        end_turn: Some(true),
        terminal_reason_code: None,
        delivery_observation: Some(observation),
