        outcome: PromptRuntimeTerminalOutcomeV1::NotDispatched,
        end_turn: None,
        terminal_reason_code: Some("cancelled_before_send".to_owned()),
        delivery_observation: None,
        observed_unix_ms: 10,
    };
    owner
        .record(record.clone())
        .unwrap_or_else(|error| panic!("record: {error}"));
