#[cfg(windows)]
fn entry_exists(directory: &File, name: &str) -> Result<bool, AuthorityLeaseError> {
    windows::entry_exists(directory, name)
}

#[cfg(windows)]
fn replace_state(directory: &File) -> Result<(), AuthorityLeaseError> {
