        let (tx, rx) = mpsc::channel();
        let expected = binding();
        std::thread::spawn(move || {
            let result = verifier.with_verified_use(token, &expected, || {
                registry.revoke("lease-one", 1, [8; 32]).unwrap();
                7
            });
            let _ = tx.send(result);
