    fn diagnostic_registry(&self) -> &PromptRegistry {
        &self.registry
    }

    #[must_use]
    pub const fn requires_reopen(&self) -> bool {
        self.poisoned
    }

    fn ensure_available(&self) -> Result<(), DurableRegistryError> {
        if self.poisoned {
            return Err(DurableRegistryError::ReopenRequired);
        }
        Ok(())
    }

