        let admission_grant = FinalUseGrant {
            schema_version: 1,
            signer_id: "security-owner:lifecycle".to_owned(),
            authority_epoch: 9,
            grant_id: "grant:lifecycle-admit".to_owned(),
            nonce: [51; 32],
