        let persisted = reopened
            .registry()
            .must("registry")
            .lifecycle_events()
            .last()
            .must("persisted revocation event");
        assert_eq!(persisted.actor_id, actor);
        assert_eq!(persisted.reason_digest, Some(reason));
        assert_eq!(persisted.cutoff_unix_ms, Some(cutoff));
    }

